protected readonly summaryByStatus = computed<StatusSummary[]>(() => {
  const claims = this.claims();
  return SUMMARY_STATUSES.map((status) => ({ status, count: claims.filter((c) => c.status === status).length }));
});
/** How many of the sheet's claims are in a status. */
protected statusCount(status: string): number {
  return this.summaryByStatus().find((s) => s.status === status)?.count ?? 0;
}
/** How many of the sheet's claims are late for review on its today. */
protected readonly reviewLateCount = computed(() => {
  const sheet = this.sheets.current();
  if (sheet === null) return 0;
  return this.claims().filter((c) => isReviewLate(c, sheet.today, sheet.reviewSla)).length;
});
  });
}

protected commentTextChanged(c: ClaimView, text: string): void {
  this.commentTexts.update((texts) => ({ ...texts, [c.id]: text }));
  if (this.claimError()?.id === c.id) this.claimError.set(null);
}

protected addComment(c: ClaimView): void {
  this.claimError.set(null);
  const sheet = this.sheets.current();
  if (!sheet) return;
  const text = (this.commentTexts()[c.id] ?? '').trim();
  if (text === '') {
    this.claimError.set({ id: c.id, message: 'Type a comment to add.' });
    return;
  }
  this.api.comment(sheet.id, c.id, text).subscribe({
    next: (saved) => {
      this.commentTexts.update((texts) => ({ ...texts, [c.id]: '' }));
      this.saved.emit(saved);
    },
    error: (err: unknown) => this.claimError.set({
      id: c.id,
      message: err instanceof HttpErrorResponse && err.status === 403
        ? 'You may not comment on this claim.'
        : 'This claim cannot be commented on now.',
    }),
  });
}

protected showTimeline(c: ClaimView): void {
  this.claimError.set(null);
  const sheet = this.sheets.current();
  if (!sheet) return;
  // The lines shown before are gone while the claim's timeline is read again.

